    for i, value in enumerate(items):
        assert value in r, (args, i)
        assert r.index(value) == items.index(value), (args, i)
        assert r[i] == value, (args, i)
    if items:
        assert r[-1] == items[-1], args
    for query in [args[0], args[1]]:
        assert (query in r) == (query in items), (args, query)
    if isinstance(args[0], float) and abs(args[2]) < 1e308:
