    ((0.0, 1.7e308, 5 * 10**307), 0.0 + 3 * (5 * 10**307), 3),
    ((0.0, -1.7e308, -5 * 10**307), 0.0 - 3 * (5 * 10**307), 3),
]:
    r = LocalRange(*args)
    assert query in r
    assert r.index(query) == expected
r = numeric_range(1.0, nextafter(1.0, inf), 1e-100)
n = r._len
assert 1.0 + (n - 1) * 1e-100 < r._stop <= 1.0 + n * 1e-100
for args in [(0, inf, 1), (0., inf, 1.), (0, -inf, -1), (0., -inf, -1.)]:
    try:
        len(numeric_range(*args))
    except ValueError:
        pass
    else:
        raise AssertionError(args)
for sign in (1, -1):
    try:
        len(numeric_range(0.0, sign * 1.7e308, sign * (5 * 10**307)))
    except OverflowError:
        pass
    else:
        raise AssertionError('actual boundary overflow was swallowed')
print('PASS: huge local queries, long float plateaus, speculative overflow and actual arithmetic errors', flush=True)

queries = [Decimal('-10'), Decimal('0'), Decimal('0.125'), Decimal('0.5'), Decimal('1'), Fraction(1, 2), 0, 1]
for prec in [3, 28]:
    for strict in [False, True]:
        for args in [(Decimal('0'), Decimal('1'), Decimal('.125')), (Decimal('1'), Decimal('0'), Decimal('-.125')), (Decimal('1E100'), Decimal('2E100'), Decimal('1E99'))]:
            for query in queries:
