                    results = []
                    for cls in (baseline.numeric_range, numeric_range):
                        with localcontext() as ctx:
                            ctx.prec = prec
                            if strict:
                                for signal in ctx.traps:
                                    ctx.traps[signal] = True
                            ctx.clear_flags()
                            try:
                                result = ('value', operation(cls(*args), query))
                            except Exception as exc:
                                result = ('exception', type(exc))
                            results.append((result, ctx.flags.copy()))
                    assert results[0] == results[1], (prec, strict, args, query, results)
print('PASS: Decimal values, exceptions and signal flags match baseline under default and all-traps contexts', flush=True)
subprocess.run([sys.executable, '-m', 'unittest'], check=True)
